{"source":"#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    int d,sum;
    scanf("%d%d",&d,&sum);
    int arr[d][2];
    int i,j;
    int result[d];
    int max_sum=0,min_sum=0;

    for(i=0;i<d;i++)
    {
        for(j=0;j<2;j++)
        {
            scanf("%d",&arr[i][j]);
        }
        max_sum+=arr[i][1];
        min_sum+=arr[i][0];
        result[i]=arr[i][0];

    }
    if(min_sum > sum || sum > max_sum)
    {
        printf("NO\n");
        return 0;
    }

    else
    {
        printf("YES\n");
        int need = sum - min_sum;
        for(i=0;i<d && need>0;i++)
        {
            int cap = arr[i][1] - arr[i][0];
            int add = cap < need ? cap : need;
            result[i] += add;
            need -= add;
        }
        for(j=0;j<d;j++)
        {
            printf("%d ",result[j]);
        }
    }
    return 0;
}"}
